"""Build the checked-in V13 SQL fixture. Run only before V13 is first deployed."""
from pathlib import Path
import math
import random

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / 'backend/iot/src/main/resources/db/migration/V13__seed_demo_stock_history.sql'


def generate():
    sql = ["""-- Generated by scripts/generate_demand_v13.py; fixed random seed 42.
-- Flyway applies this once. Do not edit after deployment.
-- All new IDs/SKUs are reserved for this fixture; existing demo catalogs are untouched.
START TRANSACTION;
SET @demand_cutoff = DATE(UTC_TIMESTAMP() + INTERVAL 7 HOUR) - INTERVAL 1 DAY;
SET @demand_w1 = (SELECT warehouse_id FROM warehouse WHERE monitoring_slot = 1 AND deleted = 0);
SET @demand_w2 = (SELECT warehouse_id FROM warehouse WHERE monitoring_slot = 2 AND deleted = 0);
INSERT INTO demand_seed_batch VALUES ('DEMAND_V13', @demand_cutoff, UTC_TIMESTAMP(6));
-- Preflight: a duplicate batch key aborts if reserved SKUs/IDs conflict or a warehouse is missing.
INSERT INTO demand_seed_batch
SELECT 'DEMAND_V13', @demand_cutoff, UTC_TIMESTAMP(6)
WHERE @demand_w1 IS NULL OR @demand_w2 IS NULL
   OR EXISTS (SELECT 1 FROM product WHERE sku LIKE 'DEMAND_V13_%' OR product_id LIKE 'd13-p%')
   OR EXISTS (SELECT 1 FROM monitored_shelf WHERE id LIKE 'd13-s%' OR device_code LIKE 'DEMAND_V13_%');
"""]
    rng = random.Random(42)
    balances = [0 if i % 3 == 0 else 40 if i % 3 == 1 else 500 for i in range(12)]
    for i in range(12):
        pid = f'd13-p{i+1:02}'
        sql.append(f"INSERT INTO product (product_id,sku,name,category,description,unit_weight,unit,deleted,created_at,updated_at) VALUES ('{pid}','DEMAND_V13_{i+1:03}','Demo nhu cầu {i+1:02}','DEMAND_DEMO','SIMULATED - Flyway V13',100,'ITEM',0,DATE_SUB(@demand_cutoff, INTERVAL 729 DAY),UTC_TIMESTAMP(6));")
        sql.append(f"INSERT INTO inventory VALUES ('d13-i{i+1:02}','{pid}',{2*balances[i]},UTC_TIMESTAMP(6));")
        for wh in (1, 2):
            sid = f'd13-s{wh}-{i+1:02}'
            sql.extend([
                f"INSERT INTO monitored_shelf (id,name,warehouse_id,device_code,capacity) VALUES ('{sid}','Kệ demo V13 {i+1:02}',@demand_w{wh},'DEMAND_V13_W{wh}_{i+1:02}',2000);",
                f"INSERT INTO monitored_shelf_product VALUES ('{sid}','{pid}');",
                f"INSERT INTO shelf_stock VALUES ('d13-ss{wh}-{i+1:02}','{sid}','{pid}',{balances[i]},UTC_TIMESTAMP(6));",
                f"INSERT INTO warehouse_inventory VALUES (@demand_w{wh},'{pid}',{balances[i]},UTC_TIMESTAMP(6));",
                f"INSERT INTO demand_policy VALUES (@demand_w{wh},'{pid}',0);",
                f"INSERT INTO demand_series VALUES (@demand_w{wh},'{pid}','SIMULATED',DATE_SUB(@demand_cutoff,INTERVAL 729 DAY),@demand_cutoff,'DEMAND_V13');",
            ])
    stocks = {(wh, i): 0 for wh in (1, 2) for i in range(12)}
    rows = []
    for day in range(730):
        for wh in (1, 2):
            for i in range(12):
                profile = i % 6
                multiplier = (1 if profile == 0 else [1.4,1.2,1,1,1.3,.65,.45][day % 7] if profile == 1
                              else .6+day/730 if profile == 2 else 1.5-.9*day/730 if profile == 3
                              else 1+.55*math.sin(2*math.pi*day/365.25) if profile == 4 else 1)
                qty = max(0, round((12+i+wh*2)*multiplier*rng.uniform(.65,1.35)))
                if profile == 5:
                    qty = 0 if rng.random() < .72 else qty*3
                incoming = qty + (balances[i] if day == 0 else 0)
                for typ, amount in [('IN', incoming), ('OUT', qty)]:
                    if amount == 0:
                        continue
                    stocks[wh, i] += amount if typ == 'IN' else -amount
                    total = sum(stocks[w, i] for w in (1, 2))
                    # UTC 01/02/03/04 corresponds to 08/09/10/11 in Vietnam.
                    hour = (wh-1)*2 + (1 if typ == 'IN' else 2)
                    rows.append(f"('d13-t{day}-{wh}-{i}-{typ}','d13-p{i+1:02}','{typ}',{amount},{total},'DEMAND_V13','SIMULATED fixture',DATE_SUB(TIMESTAMP(@demand_cutoff,'{hour:02}:00:00'),INTERVAL {729-day} DAY),@demand_w{wh},{stocks[wh,i]},'SIMULATED','DEMAND_V13')")
    header = 'INSERT INTO stock_transaction (transaction_id,product_id,type,quantity,stock_after,created_by,note,created_at,warehouse_id,warehouse_stock_after,data_source,seed_batch_id) VALUES\n'
    for offset in range(0, len(rows), 200):
        sql.append(header + ',\n'.join(rows[offset:offset+200]) + ';')
    sql.append('COMMIT;\n')
    OUTPUT.write_text('\n'.join(sql), encoding='utf-8')
    print(f'{OUTPUT.name}: {len(rows)} transactions, 24 series, 730 days')


if __name__ == '__main__':
    generate()
